source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {v: sum(row.count(v) for row in grid) for v in set(x for row in grid for x in row)}
    background = max(counts, key=counts.get)
    seen = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == background:
                seen.add((nr, nc)); q.append((nr, nc))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background and (r, c) not in seen:
                out[r][c] = 4
    return out
'''
